from modele import *
from donnees_figures import triangle,schema

def P(i,titre,enonce,corrige,methode,controle,valeurs,droit=True):
    return E(titre,enonce,corrige,methode,controle,figure=triangle(f'pyth-{i:02}',valeurs=valeurs,droit=droit))

chapitre(12,'triangle-rectangle','Pythagore, cercle et droite des milieux','4 · Espace et géométrie',
'Pythagore · Réciproque · Contraposée · Cercle circonscrit · Droite des milieux',
['Calculer une longueur dans un triangle rectangle.','Prouver ou réfuter qu’un triangle est rectangle.','Utiliser le cercle circonscrit et les théorèmes des milieux.'],['Carrés, racines carrées, médiatrices et parallélogrammes.'],[
r'''\essSection{1}{Pythagore, réciproque et contraposée}
\begin{propriete}[Théorème de Pythagore]Si ABC est rectangle en A, alors $BC^2=AB^2+AC^2$. BC, opposé à l’angle droit, est l’hypoténuse et le plus long côté.\end{propriete}
\begin{savoirfaire}[Calculer une longueur]Pour $AB=6$ cm et $AC=8$ cm, $BC^2=36+64=100$, donc $BC=\sqrt{100}=10$ cm. Si $BC=13$ cm et $AB=5$ cm, $AC^2=169-25=144$, d’où $AC=12$ cm. Une longueur est positive.\end{savoirfaire}
\begin{propriete}[Réciproque]Dans un triangle, si le carré du plus long côté est égal à la somme des carrés des deux autres, alors le triangle est rectangle, et l’angle droit est opposé au plus long côté.\end{propriete}
\begin{definition}La réciproque de « si $P$, alors $Q$ » est « si $Q$, alors $P$ ». Sa contraposée est « si $Q$ est faux, alors $P$ est faux ». Une propriété vraie a une contraposée vraie ; sa réciproque doit être démontrée à part.\end{definition}
\begin{propriete}[Contraposée de Pythagore]Si le carré du plus long côté n’est pas égal à la somme des carrés des deux autres, alors le triangle n’est pas rectangle.\end{propriete}
\begin{attention}Le théorème exige un angle droit connu : une apparence de dessin ne suffit pas. Conserver la valeur exacte d’une racine, puis arrondir à la précision demandée.\end{attention}''',
r'''\essSection{2}{Cercle circonscrit et droite des milieux}
\begin{propriete}Si ABC est rectangle en A, alors A appartient au cercle de diamètre [BC] : le centre du cercle circonscrit est le milieu de l’hypoténuse. Réciproquement, si A appartient au cercle de diamètre [BC], avec A distinct de B et de C, alors ABC est rectangle en A.\end{propriete}
\begin{propriete}[Droite des milieux]Dans un triangle ABC :
\par 1. la droite qui passe par les milieux de [AB] et de [AC] est parallèle à (BC) ;
\par 2. la droite qui passe par le milieu de [AB] parallèlement à (BC) coupe [AC] en son milieu ;
\par 3. le segment qui joint les milieux de [AB] et de [AC] mesure la moitié de BC.\end{propriete}
\begin{exemple}Si I et J sont les milieux de [AB] et [AC] et si $BC=9$ cm, alors $(IJ)\parallel(BC)$ et $IJ=4{,}5$ cm.\end{exemple}
\begin{savoirfaire}[Rédiger]Citer les hypothèses (angle droit, milieux, points sur un cercle), nommer la propriété utilisée, puis conclure en nommant précisément les objets. Pour montrer qu’un triangle n’est pas rectangle, le mot « contraposée » est attendu.\end{savoirfaire}'''],[
P(1,'Reconnaître l’hypoténuse',r"ABC est rectangle en A. Nommer l’hypoténuse et écrire l’égalité de Pythagore.",r"Le côté opposé à A est $\res{BC}$. L’égalité est $\res{BC^2=AB^2+AC^2}$. Le nom du sommet de l’angle droit détermine le bon côté.","Repérer d’abord le sommet de l’angle droit.","assert 3**2+4**2==5**2",('','','')),
P(2,'Un triangle classique',r"ABC est rectangle en A, avec AB = 6 cm et AC = 8 cm. Calculer BC.",r"Pythagore donne $BC^2=6^2+8^2=100$. Comme BC est positive, $\res{BC=10\text{ cm}}$.","Additionner les carrés pour trouver l’hypoténuse.","assert 6**2+8**2==10**2",('6 cm','8 cm','?')),
P(3,'Le côté manquant',r"ABC est rectangle en A. BC = 13 cm et AB = 5 cm. Calculer AC.",r"$AC^2=13^2-5^2=144$, donc $\res{AC=12\text{ cm}}$. AC est inférieure à l’hypoténuse 13 cm.","Isoler le carré inconnu avant d’extraire la racine.","assert 13**2-5**2==12**2",('5 cm','?','13 cm')),
P(4,'Garder une racine',r"ABC est rectangle en A. AB = 4 cm, AC = 7 cm. Donner BC exactement puis au dixième.",r"$BC^2=16+49=65$, donc $\res{BC=\sqrt{65}\text{ cm}}\approx\res{8{,}1\text{ cm}}$. L’arrondi n’est pas une égalité exacte.","Arrondir uniquement le résultat final.","assert round(math.sqrt(65),1)==8.1",('4 cm','7 cm','?')),
E('Le centre du cercle circonscrit',r"ABC est rectangle en A, avec BC = 10 cm ; O est le milieu de [BC]. Où se trouve le centre du cercle circonscrit à ABC ? Donner son rayon et la longueur OA.",r"Comme ABC est rectangle en A, A appartient au cercle de diamètre [BC]. Le centre est donc $\res{O\text{, milieu de }[BC]}$, le rayon vaut $\res{5\text{ cm}}$ et $\res{OA=5\text{ cm}}$ : la médiane issue de l’angle droit mesure la moitié de l’hypoténuse.","Relier l’angle droit au cercle de diamètre l’hypoténuse.","B=(0,0);C=(10,0);A=(Rational(18,5),Rational(24,5)); assert (A[0]-B[0])*(A[0]-C[0])+(A[1]-B[1])*(A[1]-C[1])==0 and (A[0]-5)**2+A[1]**2==25",figure='cercle-circonscrit'),
P(5,'Tester la réciproque',r"Dans ABC, AB = 9 cm, AC = 12 cm et BC = 15 cm. Le triangle est-il rectangle ?",r"BC est le plus grand côté. $15^2=225$ et $9^2+12^2=225$. Par la réciproque du théorème de Pythagore, ABC est $\res{\text{rectangle en A}}$.","Comparer les deux membres séparément.","assert 9**2+12**2==15**2",('9 cm','12 cm','15 cm'),False),
P(6,'Utiliser la contraposée',r"AB = 5 cm, AC = 7 cm et BC = 9 cm. ABC est-il rectangle ? Nommer la propriété utilisée.",r"$BC^2=81$ alors que $AB^2+AC^2=25+49=74$. Ces nombres diffèrent ; d’après la $\res{\text{contraposée du théorème de Pythagore}}$, ABC $\res{\text{n’est pas rectangle}}$.","Comparer exactement, sans se fier au dessin.","assert 5**2+7**2!=9**2",('5 cm','7 cm','9 cm'),False),
E('La droite des milieux',r"Dans le triangle ABC, I est le milieu de [AB] et J celui de [AC] ; BC = 9 cm. Que peut-on dire des droites (IJ) et (BC) ? Calculer IJ.",r"I et J sont les milieux de deux côtés : d’après le théorème de la droite des milieux, $\res{(IJ)\parallel(BC)}$ et $IJ=BC/2=\res{4{,}5\text{ cm}}$.","Citer les deux milieux avant d’appliquer le théorème.","A=(1,4);B=(0,0);C=(9,0); I=(Rational(A[0]+B[0],2),Rational(A[1]+B[1],2)); J=(Rational(A[0]+C[0],2),Rational(A[1]+C[1],2)); assert I[1]==J[1] and J[0]-I[0]==Rational(9,2)",figure='milieux-parallele'),
E('Un milieu retrouvé',r"Dans le triangle ABC, I est le milieu de [AB]. La parallèle à (BC) passant par I coupe [AC] en J. On sait que AC = 7,4 cm. Calculer AJ en justifiant.",r"La droite passe par le milieu de [AB] et elle est parallèle à (BC) : d’après le deuxième théorème des milieux, J est le milieu de [AC]. Donc $\res{AJ=3{,}7\text{ cm}}$.","Identifier le théorème dont la conclusion est un milieu.","assert Rational('7.4')/2==Rational('3.7')",figure='milieux-milieu'),
P(10,'Un angle à identifier',r"AB = 10 cm, AC = 6 cm et BC = 8 cm. Prouver que le triangle est rectangle et préciser en quel sommet.",r"Le plus grand côté est AB. $AB^2=100=36+64=AC^2+BC^2$. La réciproque du théorème de Pythagore donne un angle droit $\res{\text{en C}}$, opposé à AB. La position du dessin ne détermine pas l’angle droit.","Nommer le sommet opposé au plus long côté.","assert 6**2+8**2==10**2",('10 cm','6 cm','8 cm'),False),
P(7,'Une échelle contre un mur',r"Le mur AC est vertical et le sol AB horizontal. Une échelle BC de 5 m est posée à 1,4 m du mur. Quelle hauteur AC atteint-elle ?",r"ABC est rectangle en A, car le mur est perpendiculaire au sol. $AC^2=5^2-1{,}4^2=23{,}04$, donc $\res{AC=4{,}8\text{ m}}$. La hauteur reste inférieure à la longueur de l’échelle.","Justifier l’angle droit par le mur et le sol.","assert Rational(5)**2-Rational('1.4')**2==Rational('4.8')**2",('1,4 m','?','5 m')),
E('Un triangle dans un demi-cercle',r"[BC] est un diamètre d’un cercle de centre O et de rayon 6,5 cm. A est un point de ce cercle, distinct de B et de C, tel que AB = 5 cm. Démontrer que ABC est rectangle, puis calculer AC.",r"A appartient au cercle de diamètre [BC] et diffère de B et C : ABC est $\res{\text{rectangle en A}}$. Le diamètre vaut $BC=13$ cm. Pythagore donne $AC^2=13^2-5^2=144$, donc $\res{AC=12\text{ cm}}$.","Utiliser le cercle pour obtenir l’angle droit, puis Pythagore.","assert 2*Rational('6.5')==13 and 13**2-5**2==12**2",figure='demi-cercle'),
E('Un rectangle sans équerre',r"On trace un cercle de centre O, puis deux diamètres [AC] et [BD] qui ne sont pas perpendiculaires. Démontrer que ABCD est un rectangle. Pourquoi ce procédé permet-il de construire un rectangle sans équerre ?",r"Les diagonales [AC] et [BD] ont le même milieu O : ABCD est un parallélogramme. Elles ont la même longueur, celle d’un diamètre : un parallélogramme dont les diagonales ont même longueur est $\res{\text{un rectangle}}$. On n’a utilisé que le compas et la règle : $\res{\text{aucun angle droit n’est tracé}}$.","Utiliser une propriété caractéristique du rectangle par ses diagonales.","import math as m\nA=(5,0);C=(-5,0);B=(5*m.cos(1),5*m.sin(1));D=(-B[0],-B[1])\nassert abs((B[0]-A[0])*(D[0]-A[0])+(B[1]-A[1])*(D[1]-A[1]))<1e-9",figure='rectangle-compas'),
E('Une hauteur de triangle',r"ABC est isocèle en C : CA = CB = 13 cm et AB = 10 cm. H est le milieu de [AB]. Calculer CH puis l’aire de ABC.",r"Dans un triangle isocèle, la médiane [CH] est aussi une hauteur : ACH est rectangle en H. AH = 5 cm et $CH^2=13^2-5^2=144$, donc CH = 12 cm. L’aire vaut $10\times12/2=\res{60\text{ cm}^2}$.","Justifier la perpendicularité avant Pythagore.","assert 13**2-5**2==12**2 and 10*12/2==60",figure='pyth-iso'),
E('Le théorème de Varignon',r"ABCD est un quadrilatère quelconque, non croisé. I, J, K et L sont les milieux respectifs de [AB], [BC], [CD] et [DA]. Démontrer que IJKL est un parallélogramme.",r"Dans le triangle ABC, I et J sont des milieux : $(IJ)\parallel(AC)$ et $IJ=AC/2$. Dans le triangle ACD, L et K sont des milieux : $(LK)\parallel(AC)$ et $LK=AC/2$. Les côtés opposés [IJ] et [LK] sont donc parallèles et de même longueur : IJKL est $\res{\text{un parallélogramme}}$, quelle que soit la forme de ABCD.","Utiliser la diagonale [AC] comme intermédiaire dans deux triangles.","A=(0,0);B=(7,1);C=(8,5);D=(2,6)\nmil=lambda P,Q:(Rational(P[0]+Q[0],2),Rational(P[1]+Q[1],2))\nI,J,K,L=mil(A,B),mil(B,C),mil(C,D),mil(D,A)\nassert (J[0]-I[0],J[1]-I[1])==(K[0]-L[0],K[1]-L[1])",figure='varignon')
],reperes=['Pythagore : calculer une longueur','Réciproque et contraposée','Cercle circonscrit au triangle rectangle','Théorèmes des milieux'],deco='geometrie')

def T(i,titre,enonce,corrige,methode,controle,ratio=.6,papillon=False,labels=()):
    if papillon:
        pts={'A':(0,0),'B':(5,0),'C':(2,3),'M':(-5*ratio,0),'N':(-2*ratio,-3*ratio)}
    else: pts={'A':(0,0),'B':(5,0),'C':(2,3),'M':(5*ratio,0),'N':(2*ratio,3*ratio)}
    fig=schema(f'thales-{i:02}',pts,[('A','B'),('B','C'),('C','A'),('A','M'),('A','N'),('M','N')],labels)
    return E(titre,enonce,corrige,methode,controle,figure=fig)

chapitre(13,'thales','Thalès, réciproque et contraposée','4 · Espace et géométrie',
'Alignements · Parallèles · Rapports égaux · Réciproque · Contraposée',
['Écrire les rapports de longueurs correspondantes.','Calculer une longueur dans les deux configurations.','Démontrer que des droites sont, ou ne sont pas, parallèles.'],['Proportionnalité, fractions, produits en croix et droite des milieux.'],[
r'''\essSection{1}{Le théorème de Thalès}
\begin{propriete}[Théorème de Thalès]Si A, M, B sont alignés, A, N, C sont alignés et $(MN)\parallel(BC)$, dans la configuration des triangles emboîtés ou dans celle dite du papillon, alors
\[\frac{AM}{AB}=\frac{AN}{AC}=\frac{MN}{BC}.\]
Les longueurs des côtés correspondants des triangles AMN et ABC sont proportionnelles.\end{propriete}
\begin{savoirfaire}[Associer les côtés]Dans les triangles AMN et ABC, A correspond à A, M à B et N à C. Tous les numérateurs appartiennent au même triangle. Choisir ensuite l’égalité contenant l’inconnue et deux données.\end{savoirfaire}
\begin{exemple}Si $AM=3$, $AB=5$, $AC=7$ et les hypothèses sont vérifiées, $AN/7=3/5$, donc $AN=4{,}2$ dans la même unité.\end{exemple}
\begin{attention}Si M est entre A et B, $MB=AB-AM$. Dans le papillon, où A est entre M et B, $MB=AM+AB$. Lire l’ordre des points avant de calculer.\end{attention}
\begin{exemple}[Une preuve par les aires]Dans le cas des triangles emboîtés, les triangles MNB et MNC ont la même base [MN] et la même hauteur, car $(BC)\parallel(MN)$. Comparer les aires conduit à l’égalité des rapports : la démonstration complète figure en fin de livre.\end{exemple}''',
r'''\essSection{2}{Réciproque, contraposée et proportionnalité}
\begin{propriete}[Réciproque]Si A, M, B et A, N, C sont alignés dans le même ordre et si $\dfrac{AM}{AB}=\dfrac{AN}{AC}$, alors $(MN)\parallel(BC)$.\end{propriete}
\begin{propriete}[Contraposée]Si A, M, B et A, N, C sont alignés et si $\dfrac{AM}{AB}\ne\dfrac{AN}{AC}$, alors les droites (MN) et (BC) ne sont pas parallèles : sinon le théorème imposerait l’égalité.\end{propriete}
\begin{savoirfaire}[Comparer deux rapports]Comparer exactement, par exemple avec des produits en croix : $3/8$ et $5/12$ diffèrent, car $3\times12=36$ et $5\times8=40$. Un arrondi ne permet jamais de conclure à l’égalité.\end{savoirfaire}
\begin{propriete}[Lien avec la proportionnalité]Dans un repère, des points alignés avec l’origine ont des coordonnées proportionnelles : Thalès s’applique aux triangles formés avec leurs projetés sur l’axe des abscisses.\end{propriete}
\begin{savoirfaire}[Rédiger]Énoncer les alignements et le parallélisme, nommer le théorème, écrire l’égalité des rapports puis calculer. Dans une réciproque ou une contraposée, conclure en nommant les deux droites.\end{savoirfaire}'''],[
T(1,'Écrire les rapports',r"Dans la figure, M appartient à [AB], N à [AC] et $(MN)\parallel(BC)$. Écrire les rapports égaux.",r"Les alignements et le parallélisme permettent d’appliquer le théorème de Thalès : $\res{AM/AB=AN/AC=MN/BC}$. Les côtés du petit triangle sont tous au numérateur.","Garder la même correspondance des sommets.","assert Rational(3,5)==Rational(6,10)"),
T(2,'Une longueur réduite',r"M est sur [AB], N sur [AC] et $(MN)\parallel(BC)$. AM = 3 cm, AB = 5 cm, AC = 10 cm. Calculer AN.",r"Thalès donne $AN/10=3/5$. Ainsi $\res{AN=6\text{ cm}}$. Cette longueur est inférieure à AC, conformément à l’emboîtement.","Multiplier la grande longueur par le rapport de réduction.","assert 10*Rational(3,5)==6"),
T(3,'La petite base',r"Dans la même configuration parallèle, AM = 4 cm, AB = 10 cm et BC = 15 cm. Calculer MN.",r"$MN/15=4/10$, donc $\res{MN=6\text{ cm}}$. Le rapport des longueurs est 0,4.","Choisir le rapport portant l’inconnue.","assert 15*Rational(4,10)==6",ratio=.4),
T(4,'Retrouver le grand côté',r"M est sur [AB], N sur [AC], $(MN)\parallel(BC)$. AM = 6 cm, AN = 4 cm et AC = 10 cm. Calculer AB.",r"$6/AB=4/10$. Le produit en croix donne $4AB=60$, donc $\res{AB=15\text{ cm}}$.","Une longueur agrandie se trouve en divisant par le rapport.","assert 6/Rational(4,10)==15",ratio=.4),
T(5,'De la partie au tout',r"M est sur [AB], N sur [AC], $(MN)\parallel(BC)$. AM = 3 cm, MB = 2 cm et AC = 12 cm. Calculer AN.",r"Comme M est entre A et B, AB = 3 + 2 = 5 cm. Puis $AN=12\times3/5=\res{7{,}2\text{ cm}}$. Employer MB au dénominateur aurait associé les mauvais côtés.","Reconstituer le côté entier avant Thalès.","assert 12*Rational(3,3+2)==Rational('7.2')"),
T(6,'Démontrer un parallélisme',r"A, M, B sont alignés dans cet ordre ; A, N, C aussi. AM = 4, AB = 10, AN = 6 et AC = 15, en cm. Montrer que (MN) et (BC) sont parallèles.",r"$AM/AB=4/10=2/5$ et $AN/AC=6/15=2/5$. Les alignements dans le même ordre sont donnés. La réciproque du théorème de Thalès donne $\res{(MN)\parallel(BC)}$.","Vérifier les conditions géométriques avant les rapports.","assert Rational(4,10)==Rational(6,15)",ratio=.4),
T(7,'Des droites non parallèles',r"A, M, B et A, N, C sont alignés dans cet ordre. AM = 3, AB = 8, AN = 5, AC = 12, en cm. Les droites (MN) et (BC) sont-elles parallèles ?",r"$3/8\ne5/12$, car $3\times12=36$ et $5\times8=40$. D’après la contraposée du théorème de Thalès, les droites (MN) et (BC) $\res{\text{ne sont pas parallèles}}$.","Comparer exactement, sans arrondir les quotients.","assert 3*12!=5*8"),
T(8,'Le papillon',r"M, A, B sont alignés dans cet ordre ; N, A, C aussi. $(MN)\parallel(BC)$, AM = 3 cm, AB = 5 cm et AC = 8 cm. Calculer AN.",r"Thalès s’applique aussi au papillon : $AN/8=3/5$. Donc $\res{AN=4{,}8\text{ cm}}$. Les longueurs restent positives, même si les points sont de part et d’autre de A.","Conserver les longueurs positives dans les rapports.","assert 8*Rational(3,5)==Rational('4.8')",papillon=True),
T(9,'La distance entre deux points',r"Dans le papillon précédent, AM = 3 cm et AB = 5 cm. Calculer MB. Si AN = 4,8 cm et AC = 8 cm, calculer NC.",r"A est entre les points de chaque paire : $\res{MB=3+5=8\text{ cm}}$ et $\res{NC=4{,}8+8=12{,}8\text{ cm}}$. Une soustraction correspondrait à une autre disposition.","Lire l’ordre des points.","assert 3+5==8 and Rational('4.8')+8==Rational('12.8')",papillon=True),
T(10,'Une réciproque en papillon',r"M, A, B sont alignés dans cet ordre, ainsi que N, A, C. AM = 2,4 cm, AB = 4 cm, AN = 3 cm et AC = 5 cm. Les droites (MN) et (BC) sont-elles parallèles ?",r"$AM/AB=2{,}4/4=0{,}6$ et $AN/AC=3/5=0{,}6$. Les points sont alignés dans le même ordre, de part et d’autre de A. La réciproque du théorème de Thalès donne $\res{(MN)\parallel(BC)}$.","Contrôler l’ordre des points, puis comparer les rapports.","assert Rational('2.4')/4==Rational(3,5)",papillon=True),
E('Deux triangles de même aire',r"Dans le triangle ABC, M appartient à [AB], N à [AC] et $(MN)\parallel(BC)$. Expliquer pourquoi les triangles MNB et MNC ont la même aire. En déduire que les triangles AMC et ANB ont la même aire.",r"B et C sont sur une droite parallèle à (MN) : ils sont à la même distance de (MN). Les triangles MNB et MNC ont la même base [MN] et la même hauteur : $\res{\text{même aire}}$. Ensuite $\mathcal A(AMC)=\mathcal A(AMN)+\mathcal A(MNC)=\mathcal A(AMN)+\mathcal A(MNB)=\mathcal A(ANB)$. C’est l’idée de la preuve de Thalès par les aires.","Repérer une base commune et deux hauteurs égales.","aire=lambda P,Q,R:abs((Q[0]-P[0])*(R[1]-P[1])-(R[0]-P[0])*(Q[1]-P[1]))*Rational(1,2)\nA=(0,0);B=(10,0);C=(4,6);M=(6,0);N=(Rational(12,5),Rational(18,5))\nassert aire(M,N,B)==aire(M,N,C) and aire(A,M,C)==aire(A,N,B)",figure='thales-aires'),
E('L’ombre d’un arbre',r"Un bâton vertical de 1,5 m est planté de sorte que l’extrémité S de son ombre coïncide avec celle de l’ombre d’un arbre vertical. L’ombre du bâton mesure 2 m, celle de l’arbre 12 m, sur un sol horizontal. Les rayons du soleil sont rectilignes. Calculer la hauteur de l’arbre.",r"Le bâton et l’arbre sont verticaux, donc parallèles. Les pieds sont alignés avec S, ainsi que les sommets. Le théorème de Thalès dans les triangles emboîtés de sommet S donne $h/1{,}5=12/2$, d’où $\res{h=9\text{ m}}$. Les hypothèses de verticalité et de sol horizontal justifient le modèle.","Identifier le sommet commun et les deux parallèles.","assert Rational('1.5')*12/2==9",figure='thales-ombre'),
T(13,'Une équation dans Thalès',r"M est sur [AB], N sur [AC], (MN) est parallèle à (BC). AM = 4 cm, MB = $x$ cm, AN = 6 cm et NC = 3 cm. Trouver $x$.",r"AB = $4+x$ et AC = 9. Thalès donne $4/(4+x)=6/9=2/3$. Ainsi $12=8+2x$, donc $\res{x=2\text{ cm}}$. La valeur est positive et redonne $4/6=6/9$.","Exprimer les côtés entiers avant de résoudre.","assert solve(12-2*(4+x),x)==[2]"),
E('Calculer une largeur inaccessible',r"A, B, C forment un triangle. M est le milieu de [AB] et N le milieu de [AC] ; [BC] traverse une zone inaccessible. On mesure MN = 7,4 m. Justifier le parallélisme de (MN) et (BC), puis calculer BC.",r"M et N sont les milieux de deux côtés : par le théorème de la droite des milieux, ou par la réciproque de Thalès avec $AM/AB=AN/AC=1/2$, on a $(MN)\parallel(BC)$. Puis $MN/BC=1/2$, donc $\res{BC=14{,}8\text{ m}}$.","Séparer la preuve du parallélisme et le calcul.","assert Rational('7.4')*2==Rational('14.8')",figure='thales-milieux'),
T(15,'Un contrôle critique',r"Dans une configuration emboîtée avec (MN) parallèle à (BC), un élève écrit $AM/AB=NC/AC$. AM = 3 cm, AB = 8 cm, AC = 16 cm. Corriger et calculer NC.",r"AM correspond à AN, donc $AN/16=3/8$, d’où AN = 6 cm. Puis $NC=16-6=\res{10\text{ cm}}$. NC n’est pas un côté du petit triangle AMN.","Vérifier que chaque terme est un côté correspondant.","assert 16*Rational(3,8)==6 and 16-6==10",ratio=.375)
],reperes=['Thalès emboîté et en papillon','Réciproque du théorème de Thalès','Contraposée et non-parallélisme','Modélisation et preuve par les aires'],deco='geometrie')
